/* Peace Pathways OS v3 — independent civilian research / no diplomatic mandate.
   Architecture: catalog (static) -> issue dossier -> negotiation gates -> evidence log -> local briefing.
   Extension points: ROUTES, GATES, ISSUE_CATEGORIES, state schema, peer transport adapter.
   No game scores, AI-generated consent, analytics or background network requests. */
(()=>{'use strict';
const DATA=JSON.parse(document.getElementById('catalog').textContent),ACTORS=DATA.entities,ISSUES=DATA.solutions,SOURCES=DATA.evidence,PATHWAYS=DATA.pathways||[],TRACKS=DATA.tracks||[],PHASES=DATA.phases||[];
const actorBy=Object.fromEntries(ACTORS.map(x=>[x.id,x]));const issueBy=Object.fromEntries(ISSUES.map(x=>[x.id,x]));
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const trim=(v,n=3000)=>String(v??'').trim().slice(0,n);const allowedUrl=u=>/^https?:\/\/[^\s/]+(?:\/[^\s]*)?$/i.test(trim(u,1500));
const link=(u,label)=>allowedUrl(u)?`<a class="textlink" target="_blank" rel="noopener noreferrer" href="${esc(u)}">${esc(label||u)} ↗</a>`:`<span class="muted">${esc(label||'No source URL')}</span>`;
const stamp=()=>new Date().toISOString();const groupFor=c=>({'humanitarian':'Humanitarian','sectoral':'Sectoral restraint','armistice':'Ceasefire / monitoring','settlement':'Political settlement','diplomacy':'Diplomatic process','recovery':'Recovery','justice':'Justice / accountability','prevention':'Prevention / resilience'}[c]||c);
const ROUTES=[['brief','◈','Executive brief','Orientation'],['constraints','≡','Diplomatic constraints','Orientation'],['matrix','▦','Multi-track pathway matrix','Research'],['bargaining','⇄','Incentives & credible commitments','Delivery'],['stakeholders','◎','Stakeholder atlas','Research'],['issues','◇','Issue dossiers','Research'],['evidence','▤','Source register','Research'],['workbench','⌁','Negotiation workbench','Delivery'],['verification','⊞','Monitoring & verification','Delivery'],['decisions','▣','Decision & risk ledger','Delivery'],['collaboration','◉','Peer review room','Collaboration'],['settings','⚙','Workspace & backups','Collaboration']];
const DIRECT=new Set(['sectoral','armistice','settlement','diplomacy']);
const requiresBilateral=s=>(DIRECT.has(s.category)&&!['civilian-consultation','language-minority-rights'].includes(s.id))||['prisoner-exchanges','children-reunification','missing-persons','relief-access'].includes(s.id); // Ukraine-administered domestic minority-rights measures do not inherently require Russian assent.
const GATES=[
 {id:'law',name:'International law and rights',details:'Specify sovereignty, civilian protection, applicable humanitarian and human rights law; document conflicts requiring legal review.',for:()=>true},
 {id:'owner',name:'Authorized institutional owner',details:'Identify who has the competence and domestic authorization to negotiate, approve, fund or implement this action.',for:()=>true},
 {id:'ukraine',name:'Ukrainian authorized assent',details:'For any direct cross-border or interstate arrangement, a relevant empowered Ukrainian counterpart must explicitly agree.',for:s=>requiresBilateral(s)},
 {id:'russia',name:'Russian authorized assent',details:'For any action requiring Russian restraint, access or cooperation, obtain explicit agreement from an empowered Russian counterpart.',for:s=>requiresBilateral(s)},
 {id:'strategic',name:'Strategic incentive compatibility',details:'Document both parties’ publicly supportable alternatives to agreement, ability to sustain hostilities, and what credible incentive could make a specific restraint worthwhile; do not invent hidden motives or tactical assessments.',for:s=>DIRECT.has(s.category)},
 {id:'domestic',name:'Domestic approval and treaty competence',details:'Identify which domestic institutions, constitutional procedures, budget approvals and ratification steps are required; an envoy cannot unilaterally bind them.',for:s=>['armistice','settlement','diplomacy'].includes(s.category)},
 {id:'command',name:'Effective time and command-to-compliance chain',details:'At policy level specify sign-off, synchronized effective date, instructions to responsible chains and what independently confirms implementation. Never publish tactical units or positions.',for:s=>['sectoral','armistice'].includes(s.category)},
 {id:'thirdparty',name:'Guarantor / intermediary mandate',details:'Named monitors, intermediaries, EU/NATO bodies or guarantors must separately accept the precise role; no third party can be volunteered.',for:s=>['armistice','settlement','diplomacy'].includes(s.category)||['prisoner-exchanges','children-reunification','relief-access','nuclear-safety'].includes(s.id)},
 {id:'security',name:'Operational safety and access',details:'Ensure safe humanitarian access, monitor protection and constraints on force are specified without exposing sensitive positions.',for:s=>!['export-diligence','information-integrity','risk-forecast'].includes(s.id)},
 {id:'verification',name:'Independent verification and disputes',details:'Specify indicators, source triangulation, reporting cadence, access restrictions and a dispute process for contested incidents.',for:()=>true},
 {id:'breach',name:'Non-compliance response',details:'Identify proportionate, lawful responses to refusal, obstruction, violations or collapse of monitoring. Never assume automatic enforcement.',for:s=>DIRECT.has(s.category)||s.category==='humanitarian'},
 {id:'resources',name:'Funded capacity and delivery owner',details:'Name credible resources, authorized budget/implementation owner, procurement controls and long-term operation/maintenance.',for:()=>true},
 {id:'civilian',name:'Civilian consultation and safeguards',details:'Check non-coercion, inclusion, privacy, displacement, gender and disability access, humanitarian neutrality as relevant.',for:()=>true},
 {id:'reversibility',name:'Escalation stop and fallback',details:'Define what triggers suspension, who can invoke it, and how aid and information stay protected if talks fail.',for:()=>true}
];
const TENSIONS=[
 ['Wartime leverage versus negotiating preferences','Public stated demands, ability to continue fighting, economic costs, external support and domestic political survival can diverge. Do not assume humanitarian logic alone changes bargaining incentives.'],
 ['Force posture versus settlement viability','A ceasefire must be transmitted through competent command chains, address verification and escalation risks, and account for changing military realities without exposing tactical details.'],
 ['Coalition commitments versus geopolitical leverage','Sanctions, aid, reconstruction finance, legal immunity and security assistance have different authorizers and time horizons. A facilitator cannot exchange what it does not control.'],
 ['Ceasefire versus settlement','A short restraint period is not the same as a recognized political settlement. Sequence, territorial positions, protection and elections may be disputed.'],
 ['Control versus lawful sovereignty','De facto control and internationally recognized borders are different categories. No draft may silently convert one into the other.'],
 ['Guarantees versus assurances','A guarantee needs a named, authorized guarantor, activation conditions, means, domestic authority and response to breach.'],
 ['Monitoring versus enforcement','Observers can collect and report only within mandate/access/security limits; they cannot necessarily compel compliance.'],
 ['Humanitarian neutrality versus bargaining','Protected-person rights cannot be traded away. Humanitarian channels may need deliberate separation from political bargaining.'],
 ['Coalition alignment versus veto points','Ukraine, Russia, EU members, NATO allies and other implementers have different decision rights; one stakeholder cannot pledge the others.'],
 ['Incentives versus reversibility','Relief, sanctions, financing and reconstruction involve domestic law, third parties and credible reversibility; a website cannot deliver these.'],
 ['Disclosure versus personal safety','Publish aggregated evidence and voluntary drafts, not personnel lists, protected records, locations, tactical details or private access routes.']
];
const DEFAULT_PROTOCOL={scope:'',definition:'',ownership:'',baseline:'',access:'',monitor:'',incident:'',dispute:'',response:'',protection:'',duration:''};
const fresh=()=>({schema:2,cases:[],userSources:[],prefs:{theme:'light'},created:stamp(),updated:stamp()});
let state=fresh(),store='Initialising',ui={route:'brief',q:'',matrixTrack:'all',matrixPath:PATHWAYS[0]?.id||'',actor:'ukraine',issue:'energy-truce',caseId:null,peer:{state:'disconnected',code:'peace-pathways-community-v1',room:null,action:null,peers:new Set(),incoming:[],error:'',strategy:'nostr'}};
const id=prefix=>prefix+'-'+(globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2));
const dbName='peace-accord-workbench-v2';
async function openDb(){return new Promise((resolve,reject)=>{if(!indexedDB){reject(Error('IndexedDB unavailable'));return}let r=indexedDB.open(dbName,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('root'))r.result.createObjectStore('root')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function load(){try{let db=await openDb();let w=await new Promise((resolve,reject)=>{let r=db.transaction('root').objectStore('root').get('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});db.close();store='IndexedDB';return w}catch{try{store='localStorage';return JSON.parse(localStorage.getItem(dbName)||'null')}catch{store='volatile memory';return null}}}
let persistTimer;function save(){state.updated=stamp();clearTimeout(persistTimer);persistTimer=setTimeout(async()=>{try{if(store==='IndexedDB'){let db=await openDb();await new Promise((resolve,reject)=>{let t=db.transaction('root','readwrite');t.objectStore('root').put(state,'workspace');t.oncomplete=resolve;t.onerror=()=>reject(t.error)});db.close()}else if(store==='localStorage'){localStorage.setItem(dbName,JSON.stringify(state))}else{showToast('Changes are session-only; export a backup.')}}catch{store='volatile memory';showToast('Storage failed — export a backup to retain changes.')}updateStore()},120)}
function updateStore(){if($('storageIndicator'))$('storageIndicator').textContent='Storage: '+store+' · JSON backup recommended.'}
function showToast(s){let t=$('toast');t.textContent=s;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),4500)}
function banner(title,sub,kicker='RESEARCH & DESIGN'){return `<div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p>`}
function footer(){return `<footer class="footer"><b>Independent public-interest research; not an official peace process.</b> Reference snapshot: 16 October 2026. Evidence and legislative status must be rechecked before use. No automated diplomacy, external data collection, authorization or operational monitoring. Local entries are user assertions requiring external verification. Zero-harm: do not upload or transmit identifying details of protected people, sensitive military locations, confidential negotiations or tactical information. Foster + Navi / Planetary Restoration Archive · <a href="./ATTRIBUTIONS_AND_LICENSES.md">Attributions</a>.</footer>`}
function chip(s,c=''){return `<span class="chip ${esc(c)}">${esc(s)}</span>`}
function selection(v,items){return items.map(([val,label])=>`<option value="${esc(val)}" ${v===val?'selected':''}>${esc(label)}</option>`).join('')}
function current(){return state.cases.find(x=>x.id===ui.caseId)||state.cases[0]||null}
function renderNav(){let last='';$('routeNav').innerHTML=ROUTES.map(([slug,icon,label,group])=>`${group!==last?(last=group,`<div class="navgroup">${esc(group)}</div>`):''}<a class="navlink" ${ui.route===slug?'aria-current="page"':''} href="#/${slug}"><span aria-hidden="true">${icon}</span>${esc(label)}</a>`).join('');updateStore()}
function render(){renderNav();const views={brief, constraints, matrix, bargaining, stakeholders,issues,evidence,workbench,verification,decisions,collaboration,settings};$('main').innerHTML=(views[ui.route]||notFound)()+footer();$('netStatus').textContent=navigator.onLine?'Online · local data':'Offline · local data';document.documentElement.dataset.theme=state.prefs.theme;}
function notFound(){return banner('Page not found','Use the left navigation to return to a supported research module.')+'<a href="#/brief" class="btn">Executive brief</a>'}
function route(){const slug=decodeURIComponent(location.hash.replace(/^#\/?/,'')||'brief').split('/')[0];ui.route=ROUTES.some(x=>x[0]===slug)?slug:'unknown';$('nav').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});}
function searchText(obj){return JSON.stringify(obj).toLowerCase()}
function brief(){let blocked=state.cases.filter(c=>assessment(c).status==='BLOCKED').length;return `<section class="hero">${banner('From conceptual pathways to accountable negotiation design','A structured desk for testing proposals against diplomatic authority, international law, credible guarantees, monitoring access, implementation resources and civilian safety. This workspace cannot end a war; it can make weak proposals visible before anyone mistakes them for an executable agreement.','RUSSIA–UKRAINE · INDEPENDENT WORKBENCH')}<div class="actions"><a href="#/workbench" class="btn primary">Open negotiation workbench</a><a href="#/constraints" class="btn">Examine hard constraints</a><a href="#/evidence" class="btn">Review evidence provenance</a></div><div class="notice critical"><b>Research baseline — not live:</b> October 2026 reporting documents incompatible public positions and continuing civilian harm. No ceasefire, guarantor commitment, OSCE deployment or official endorsement is assumed. Every proposed action requires independent verification.</div></section>
<div class="grid tight"><div class="card"><div class="stat">${ISSUES.length}</div><div class="label">Issue templates; not agreed terms</div></div><div class="card"><div class="stat">${ACTORS.length}</div><div class="label">Potential stakeholders; participation unverified</div></div><div class="card"><div class="stat">${state.cases.length}</div><div class="label">Local research cases</div></div><div class="card"><div class="stat">${blocked}</div><div class="label">Cases with explicit blockers</div></div></div>
<h2>Three distinct, non-substitutable layers</h2><div class="grid"><div class="card"><span class="kicker">01 · Immediate protection</span><h3>Humanitarian arrangements</h3><p>Prisoner and child reunification mechanisms, aid access, nuclear safety and limited civilian protection measures. Narrow deals may be possible without a comprehensive settlement, but still need safe access and party consent.</p><button class="btn sm" data-act="example" data-issue="prisoner-exchanges">Examine prisoner exchanges</button></div><div class="card"><span class="kicker">02 · Cessation of hostilities</span><h3>Mutual military restraint and credible observation</h3><p>Defined scope, bilateral authority, synchronized acceptance, reporting, incident investigation, monitoring security, non-compliance consequences and escalation safeguards.</p><button class="btn sm" data-act="example" data-issue="energy-truce">Examine energy restraint</button></div><div class="card"><span class="kicker">03 · Durable political and economic terms</span><h3>Security, law and reconstruction</h3><p>Sovereignty, enforceable security arrangements, sanctions law, financing, justice, return rights and reconstruction governance each have distinct institutional owners and legal veto points.</p><button class="btn sm" data-act="example" data-issue="security-guarantees">Examine security guarantees</button></div></div>
<h2>What changed from v1.1?</h2><div class="two"><div class="card"><h3>Removed</h3><p>XP, completion badges, rankings, randomized diplomatic pairings, simulated likelihood scores, progress HUD, and a fictional ladder from learning to peace.</p></div><div class="card"><h3>Added</h3><p>Prerequisite gates, documented positions, veto actors, consent checkpoints, noncompliance protocols, evidence-linked claims, adversarial review, audit trail and exportable briefing memos.</p></div></div><h2>Current reference signals</h2><div class="grid">${['ohchr-sep','reuters-ceasefire-2026','reuters-energy-2026','reuters-aid-2026'].map(k=>{let s=SOURCES.find(x=>x.id===k);return s?`<article class="card"><span class="kicker">${esc(s.date)} · ${esc(s.class)}</span><h3>${esc(s.name)}</h3><p>${esc(s.claim)}</p>${link(s.url,'Read primary or cited reporting')}</article>`:''}).join('')}</div>`}
function constraints(){return banner('Diplomatic constraints & veto map','A non-exhaustive analytical model of actors, recognition, negotiating sequence, command authority, legal obligations and implementation constraints. Positions are dated; classified intentions and bargaining ranges are unknown.','REAL-WORLD NEGOTIATION MECHANICS')+`<div class="notice warning"><b>Model discipline:</b> Actor capability is not willingness. A public statement is not a signed agreement. A signed text is not compliance. A monitor is not an enforcer. An analytical seat is not authority.</div><div class="grid">${TENSIONS.map(([h,t])=>`<article class="card"><h3>${esc(h)}</h3><p>${esc(t)}</p></article>`).join('')}</div><h2>Consent and decision rights</h2><div class="tablewrap"><table><thead><tr><th>Actor type</th><th>Can decide</th><th>Cannot be assumed to decide</th></tr></thead><tbody><tr><td>Ukraine's competent authorities</td><td>Ukrainian security, territorial and legal commitments within their authority</td><td>Russian actions; international actors' funding or defense commitments</td></tr><tr><td>Russia's competent authorities</td><td>Russian restraint, withdrawal and Russian commitments within their authority</td><td>Ukrainian sovereignty or consent; third-state legal recognition</td></tr><tr><td>Facilitators / intermediaries</td><td>Whether to facilitate, within their own mandates and the parties' consent</td><td>Bind belligerents to cease fire</td></tr><tr><td>Guarantors, NATO / EU actors</td><td>Commitments through their separate domestic or organizational processes</td><td>Be volunteered as guarantors by a third party's plan</td></tr><tr><td>Verification organizations</td><td>Observe/report if a new mandate, resources and safe access exist</td><td>Compel compliance without explicit authority</td></tr><tr><td>Local communities / humanitarian bodies</td><td>Needs identification, safeguards and legitimate local delivery within their remit</td><td>Sign a sovereign interstate settlement</td></tr></tbody></table></div>
<h2>Strategic and political feasibility screen</h2><div class="tablewrap"><table><thead><tr><th>Decision variable</th><th>Evidence needed (safe, aggregate)</th><th>Failure of analysis</th></tr></thead><tbody><tr><td>War continuation incentives</td><td>Dated public objectives, sustainability assessments from multiple independent sources, competing narratives and uncertainty</td><td>Assuming a peace dividend automatically beats perceived military alternatives</td></tr><tr><td>Domestic authority and legitimacy</td><td>Constitutional competences, legislative approvals, political constraints and public positions</td><td>Confusing a leader's speech with binding national consent</td></tr><tr><td>External leverage and veto players</td><td>Funding, guarantee, sanctions and alliance decision rights, with explicit ratification dependencies</td><td>Offering concessions controlled by unrelated institutions</td></tr><tr><td>Military de-escalation credibility</td><td>Public top-level agreed prohibitions, start/stop rules, responsible authorities, safe monitoring and independent reports</td><td>Assuming command compliance or frictionless verification</td></tr><tr><td>Bargaining sequence</td><td>Possible limited humanitarian steps, partial restraint, monitored armistice and sovereign settlement—each with its own consent conditions</td><td>Conflating a sectoral announcement with a comprehensive peace agreement</td></tr><tr><td>Sanctions and recovery incentives</td><td>Relevant statutes, lawfully reversible measures, independent audited delivery and governance</td><td>Inventing sanction-relief powers or unenforceable reconstruction promises</td></tr></tbody></table></div><h2>Dated public-position anchors</h2><div class="grid">${['uk-e3-jun','paris-2026','reuters-ceasefire-2026','reuters-zone-2026'].map(k=>{let s=SOURCES.find(x=>x.id===k);return s?`<div class="card"><span class="kicker">${esc(s.date)} · ${esc(s.class)}</span><h3>${esc(s.name)}</h3><p>${esc(s.claim)}</p>${link(s.url,'Check original context')}</div>`:''}).join('')}</div><div class="notice critical"><b>Active contradictions are not balanced away by a scoring system.</b> The position of any party may change; evaluate proposals from multiple dated sources and document irreconcilable requirements before asking whether a mediator can deliver them.</div><h2>Five non-negotiable evaluation questions</h2><ol><li>Which empowered body must agree and how is its explicit agreement recorded?</li><li>What specific action changes and which mutually incompatible positions obstruct it?</li><li>What evidence distinguishes a promise from behavior, who may inspect, and what happens when access fails?</li><li>Who pays, secures, delivers and maintains the arrangement, and what happens when enforcement is contested?</li><li>What does a failed or manipulated agreement do to civilians, sovereignty and future bargaining incentives?</li></ol><div class="actions"><a href="#/workbench" class="btn primary">Apply these checks to a case</a></div>`}
function stakeholderDetails(a){let m=a.stakeholderModel||{};return `<article class="card profile-scroll" tabindex="0" aria-label="Independently scrollable stakeholder dossier"><span class="kicker">${esc(a.kind||'candidate actor')} · CAPABILITY MODEL</span><h2>${esc(a.name)}</h2>${chip('Engagement not verified','warn')}<p><b>Authority / remit model:</b> ${esc(a.mandate)}</p><p><b>Constraints:</b> ${esc(a.constraint)}</p><p><b>Potential capabilities:</b> ${(a.capabilities||[]).map(x=>chip(x)).join('')}</p><hr class="divider"><h3>What is and is not established</h3><p>${esc(m.inferredIncentive||'Potential incentive unknown')}</p><p><b>Red lines:</b> ${esc(m.redLines||'Unverified')}</p><p><b>Alternative to an agreement (BATNA):</b> ${esc(m.BATNA||'Unverified')}</p><p><b>Failure / spoiler considerations:</b> ${esc(m.spoilerRisk||'Requires research')}</p><div class="notice warning">This profile is a research hypothesis. It is not an official statement of willingness or authorization. Validate with attributable, dated sources.</div><div class="actions"><button class="btn primary" data-act="case-actor" data-id="${esc(a.id)}">Add as proposed stakeholder</button><a href="#/evidence" class="btn">Source register</a></div><h3>Verification prompts</h3><p>What legal instrument grants competence? Is there a dated public position, a negotiable range, and a named authorized representative? What evidence would falsify our assumption?</p></article>`}
function stakeholders(){let q=ui.q.toLowerCase(),visible=ACTORS.filter(x=>!q||searchText({name:x.name,capabilities:x.capabilities,mandate:x.mandate}).includes(q));let sel=actorBy[ui.actor]||ACTORS[0];return banner('Stakeholder atlas','Exploratory actor capability and institutional authority profiles, not a ranking of importance or readiness. Select a profile; the right-side dossier scrolls independently.',ACTORS.length+' HYPOTHETICAL PARTICIPATION PROFILES')+`<div class="catalog-layout"><div class="card"><p class="small muted">${visible.length} candidates match the search. Selection is not endorsement.</p><div class="catalog-scroll" tabindex="0">${visible.map(a=>`<button class="clickrow" data-act="select-actor" data-id="${esc(a.id)}" aria-pressed="${a.id===ui.actor}"><strong>${esc(a.name)}</strong><small>${esc(a.kind)} · ${esc((a.capabilities||[]).slice(0,4).join(', '))}</small></button>`).join('')||'<p>No matching stakeholders.</p>'}</div></div>${stakeholderDetails(sel)}</div>`}
function issueDetails(s){return `<article class="card profile-scroll" tabindex="0" aria-label="Independently scrollable issue dossier"><span class="kicker">${esc(groupFor(s.category))} · NOT AN AGREED PLAN</span><h2>${esc(s.title)}</h2><p>${esc(s.outcome)}</p><h3>First legitimate research move</h3><p>${esc(s.first)}</p><h3>Evidence and monitoring</h3><p>${esc(s.verify)}</p><h3>Failure mode</h3><p>${esc(s.failure)}</p><h3>Legal constraints</h3><p>${esc(s.legal)}</p><h3>Conditional exchanges — hypothetical only</h3><p>${esc(s.conditionalExchange||'Not specified; consult qualified parties.')}</p><h3>Dependencies</h3><ul>${(s.dependencies||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Operational execution and acceptance evidence</h3>${(s.executionSteps||[]).map(st=>`<details><summary>Step ${esc(st.order)} · ${esc(st.owner)}</summary><p>${esc(st.action)}</p><p><b>Acceptance evidence:</b> ${esc(st.acceptanceEvidence)}</p></details>`).join('')}<h3>Risk / stop register</h3>${(s.risks||[]).map(r=>`<p><b>${esc(r.risk)}</b> — ${esc(r.mitigation)}<br><span class="muted small">Stop/review if: ${esc(r.stopOrReviewTrigger)}</span></p>`).join('')}<h3>Quantitative design criteria</h3>${(s.metrics||[]).map(m=>`<div class="decision"><b>${esc(m.label)} (${esc(m.unit)})</b><p>${esc(m.definition)}</p><p>Target: ${esc(m.proposalTarget)} · Baseline: ${esc(m.baseline)} · Independent validation: ${esc(m.validation)}</p></div>`).join('')}<h3>Proposed implementation stages</h3>${(s.stages||[]).map(t=>`<details><summary>${esc(t.phase)} — ${esc(t.heading)}</summary><p>${esc(t.action)}</p><p><b>Review:</b> ${esc(t.checkpoint)}</p></details>`).join('')}<p><b>Resource uncertainty:</b> ${esc(s.costBand||'Unknown; no verified cost estimate.')}</p><div class="actions"><button class="btn primary" data-act="example" data-issue="${esc(s.id)}">Create research case</button></div><div class="notice warning">Proposed actors, costs, timetables and stages are hypotheses until independently validated. There is no automated request to institutions.</div></article>`}
function issues(){let q=ui.q.toLowerCase(),visible=ISSUES.filter(x=>!q||searchText({title:x.title,category:x.category,outcome:x.outcome,tags:x.tags}).includes(q));let selected=issueBy[ui.issue]||ISSUES[0];return banner('Issue dossiers','Browse 32 preserved issue families and 13 operationally modeled constraints. Each is now a candidate policy instrument with an explicit failure mode and documented dependencies, not a “solution unlocked.”',ISSUES.length+' PROPOSAL TEMPLATES')+`<div class="catalog-layout"><div class="card"><p class="small muted">${visible.length} dossiers match the search.</p><div class="catalog-scroll" tabindex="0">${visible.map(s=>`<button class="clickrow" data-act="select-issue" data-id="${esc(s.id)}" aria-pressed="${s.id===ui.issue}"><strong>${esc(s.title)}</strong><small>${esc(groupFor(s.category))}</small></button>`).join('')||'<p>No matching issues.</p>'}</div></div>${issueDetails(selected)}</div>`}
function caseFactory(solutionId){let s=issueBy[solutionId]||ISSUES[0];return {id:id('case'),title:s.title+' — research draft',issueId:s.id,category:s.category,description:s.outcome,owner:'',forum:'',scope:'',next:'Identify an authorized institutional owner and independently review current positions.',actors:[],gates:{},protocol:{...DEFAULT_PROTOCOL},incentives:{},entries:[],created:stamp(),updated:stamp(),status:'EXPLORATORY / UNAUTHORIZED'}}
function reqGates(c){let s=issueBy[c.issueId]||ISSUES[0];return GATES.filter(g=>g.for(s))}
function assessment(c){let gates=reqGates(c),blocked=[],missing=[],documented=[];for(let g of gates){let x=c.gates[g.id]||{state:'unknown'};if(x.state==='blocked')blocked.push(g.name);else if(x.state==='documented'&&allowedUrl(x.url)&&trim(x.note).length>=12)documented.push(g.name);else missing.push(g.name)}let status=blocked.length?'BLOCKED':missing.length?'UNRESOLVED':'DOCUMENTATION RECORDED — INDEPENDENT REVIEW REQUIRED';return {status,blocked,missing,documented,total:gates.length}}
function casePanel(){let c=current();return `<div class="card"><div class="row between"><label class="field" style="min-width:230px;flex:1">Active research case<select id="caseSelect">${state.cases.map(x=>`<option value="${esc(x.id)}" ${x.id===c?.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><button class="btn" data-act="new-case">New case</button><button class="btn danger" data-act="delete-case" ${!c?'disabled':''}>Delete case</button></div></div>`}
function workbench(){let c=current();let issue=issueBy[c?.issueId];let a=c?assessment(c):null;return banner('Negotiation workbench','Create issue-specific dossiers with accountable ownership, documented actor participation, readiness blockers, evidence-linked authorization assertions and explicit next moves. No hypothetical combination can override a missing gate.','DECISION SUPPORT · HUMAN REVIEW REQUIRED')+casePanel()+(!c?`<div class="card spaced"><h2>No cases yet</h2><p>Start from an issue dossier or create a blank research case. Source catalog data is preserved, and all work remains on this device unless you explicitly export or share it.</p><div class="actions"><button class="btn primary" data-act="example" data-issue="energy-truce">Open energy-restraint example</button><button class="btn" data-act="example" data-issue="relief-access">Open humanitarian-access example</button></div></div>`:`<div class="decision ${a.blocked.length?'danger':''}"><div class="row between"><div><div class="kicker">Evidence discipline · no authority implied</div><h3>${esc(a.status)}</h3><p>${a.documented.length}/${a.total} prerequisites include user-entered supporting references; ${a.missing.length} unresolved; ${a.blocked.length} marked blocked.</p></div><button class="btn" data-act="review">Reassess documentation</button></div><p class="small">Even a complete reference set is <b>not a verified agreement or permission to implement</b>. External competent review is essential.</p></div>
<form id="caseForm" class="card spaced"><h2>Case definition</h2><div class="formgrid"><label class="field">Title<input name="title" required maxlength="170" value="${esc(c.title)}"></label><label class="field">Issue family<select name="issueId">${selection(c.issueId,ISSUES.map(s=>[s.id,s.title]))}</select></label><label class="field">Potential institutional owner<input name="owner" maxlength="170" value="${esc(c.owner)}" placeholder="Unverified until documented"></label><label class="field">Proposed forum / convener<input name="forum" maxlength="170" value="${esc(c.forum)}" placeholder="Consent not yet established"></label><label class="field wide">Desired change and limits<textarea name="description" maxlength="3000">${esc(c.description)}</textarea></label><label class="field wide">Scope / exclusions<textarea name="scope" maxlength="3000" placeholder="Specify limited civilian-safe policy scope; no operational coordinates or sensitive records">${esc(c.scope)}</textarea></label><label class="field wide">Next reviewable action<textarea name="next" maxlength="3000">${esc(c.next)}</textarea></label></div><div class="actions"><button class="btn primary" type="submit">Save case definition</button><button type="button" class="btn" data-act="export-memo">Export briefing memo (.md)</button><button type="button" class="btn" data-act="export-case">Export case JSON</button></div></form>
<div class="card spaced"><h2>Stakeholder participation hypotheses</h2><p class="small muted">Adding an actor never implies consent. Name their role and evidence requirements, then seek appropriate authorization outside this application.</p><div class="formgrid"><label class="field">Proposed actor<select id="actorAdder">${ACTORS.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('')}</select></label><label class="field">Proposed role<input id="roleAdder" maxlength="140" placeholder="e.g., intermediary — subject to acceptance"></label></div><button class="btn" data-act="add-actor">Add proposed actor</button><div class="tablewrap"><table><thead><tr><th>Actor</th><th>Possible role</th><th>Mandate status</th><th></th></tr></thead><tbody>${c.actors.length?c.actors.map((x,i)=>`<tr><td>${esc(actorBy[x.id]?.name||x.id)}</td><td>${esc(x.role)}</td><td>Unverified — ${esc(x.status||'proposal')}</td><td><button class="btn sm danger" data-act="remove-actor" data-index="${i}">Remove</button></td></tr>`).join(''):'<tr><td colspan="4">No proposed partners; none presumed.</td></tr>'}</tbody></table></div></div>
<div class="card spaced"><h2>Institutional prerequisite register</h2><p>For each prerequisite, choose <b>Unknown</b>, <b>Evidence entered</b>, or <b>Blocked</b>. “Evidence entered” is counted only when a public HTTP(S) link and explanatory note are supplied; these entries are not independently validated.</p>${reqGates(c).map(g=>{let val=c.gates[g.id]||{};return `<section class="gate"><div class="gate-head"><div><b>${esc(g.name)}</b><p class="small muted" style="margin:4px 0">${esc(g.details)}</p></div>${val.state==='blocked'?chip('Blocker','danger'):val.state==='documented'?chip('Submitted claim','warn'):chip('Unknown','warn')}</div><div class="gate-body"><label class="field">Review status<select data-gate="${g.id}" data-part="state">${selection(val.state||'unknown',[['unknown','Unknown / not established'],['documented','Evidence entered (requires verification)'],['blocked','Blocked / contradicted']])}</select></label><label class="field">Public evidence URL<input type="url" data-gate="${g.id}" data-part="url" maxlength="1500" placeholder="https://…" value="${esc(val.url||'')}"></label><label class="field">Documented basis / unresolved question<input data-gate="${g.id}" data-part="note" maxlength="800" placeholder="What exactly does the source establish?" value="${esc(val.note||'')}"></label></div></section>`}).join('')}<div class="actions"><button class="btn primary" data-act="review">Save checks and reassess</button><a href="#/verification" class="btn">Design verification protocol</a></div></div>
<div class="two"><div class="card warn"><h3>Negotiation friction</h3><p><b>Failure condition:</b> ${esc(issue?.failure||'Unknown')}</p><p><b>Legal review:</b> ${esc(issue?.legal||'Unknown')}</p></div><div class="card"><h3>Testable deliverables</h3><p><b>Observable indicator:</b> ${esc(issue?.independentMetric||issue?.metric||'Not defined')}</p><p><b>Cost basis:</b> ${esc(issue?.costBand||'Unknown; do not infer.')}</p></div></div>`)}
function verification(){let c=current();if(!c)return banner('Monitoring & verification','Create a case in the negotiation workbench to define a monitorable mechanism.')+'<a href="#/workbench" class="btn primary">Create case</a>';return banner('Monitoring & verification protocol','Specify what is observed, how disputes and obstruction are handled, and what fails safely. An unaccepted protocol is an analytical draft; an observer mission requires a real mandate.','NOT A LIVE CEASEFIRE MONITOR')+`<div class="notice critical"><b>Historical guardrail:</b> the OSCE Special Monitoring Mission ceased operations in 2022. It cannot simply be assigned a future mission. A new operation needs party consent, a new authorizing instrument, safe access, resources and independent incident review. ${link(SOURCES.find(x=>x.id==='osce-closed')?.url,'OSCE archival record')}</div><div class="card spaced"><div class="row between"><h2>${esc(c.title)}</h2>${chip('Research draft','warn')}</div><form id="protocolForm"><div class="formgrid">${[
 ['scope','Covered commitments and exclusions','What conduct / facilities are covered; what is excluded?'],['definition','Terms and observable indicators','Definitions, time windows, public baseline, threshold and measurement uncertainty'],['ownership','Institutional authority and reporting chain','Who authorizes monitors, who receives reports?'],['baseline','Baseline and independent evidence','Which independent sources establish incidents and pre/post conditions?'],['access','Access and monitor protection','What safe, lawfully granted access is required; what if access is denied?'],['monitor','Method and cadence','Aggregate indicators, corroboration, reporting cadence and limits'],['incident','Incident intake and attribution','Conflicting allegations, evidence preservation and non-disclosure of sensitive details'],['dispute','Independent investigation and appeal','Disagreement management, contested data, due process and correction'],['response','Breach and obstruction response','Proportionate lawful responses, freeze conditions, who has authority'],['protection','Civilian safety and privacy','IHL, sensitive records, consent, safeguarding and harm review'],['duration','End condition and sustainability','Renewal, exit, financing, operational handover']].map(([k,label,placeholder])=>`<label class="field ${['scope','definition','response'].includes(k)?'wide':''}">${esc(label)}<textarea name="${k}" maxlength="2200" placeholder="${esc(placeholder)}">${esc(c.protocol?.[k]||'')}</textarea></label>`).join('')}</div><div class="actions"><button type="submit" class="btn primary">Save verification protocol</button><button type="button" class="btn" data-act="export-memo">Export full case memo</button></div></form></div><div class="card"><h3>Adversarial verification test</h3><ul><li>A party announces a ceasefire without the other party agreeing.</li><li>Inspection access is refused, delayed, restricted or dangerous.</li><li>Remote reports cannot distinguish between an alleged attack and independently verified facts.</li><li>A guarantor lacks domestic authorization or sufficient enforcement capacity.</li><li>A monitoring mission becomes dangerous to civilians or field staff.</li></ul><p>For each test, specify a safe halt, independent clarification and what public claim must not be made.</p></div>`}
function decisions(){let c=current();if(!c)return banner('Decision & risk ledger','Create a case to record evidence, assumptions, disagreements and failure modes.')+'<a href="#/workbench" class="btn primary">Open workbench</a>';let a=assessment(c);return banner('Decision & risk ledger','Every assertion is dated as a local analyst entry, not a recorded institutional decision. Keep assumptions, evidence, objections and revisions separable.','TRACEABLE HUMAN REVIEW')+`<div class="card"><div class="row between"><h2>${esc(c.title)}</h2>${chip(a.status,a.blocked.length?'danger':'warn')}</div><div class="two"><div><h3>Unresolved prerequisites</h3><ul>${a.missing.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>None documented as missing; independent verification still required.</li>'}</ul></div><div><h3>Explicit contradictions / blockers</h3><ul>${a.blocked.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>No blockers recorded; absence of records is not absence of obstacles.</li>'}</ul></div></div></div><div class="card spaced"><h2>Record a decision, falsification test or risk</h2><form id="entryForm"><div class="formgrid"><label class="field">Entry type<select name="type">${selection('risk',[['risk','Risk / red-team'],['claim','Claim to verify'],['decision','Analyst decision'],['objection','Counterparty / civilian objection'],['update','Source or revision'],['next','Next review action']])}</select></label><label class="field">Supporting public URL (optional)<input type="url" name="url" maxlength="1500" placeholder="https://…"></label><label class="field wide">Observation, rationale or falsification criterion<textarea name="text" required maxlength="2400" placeholder="Describe a testable assertion, who would confirm it, and what would change this conclusion"></textarea></label></div><button class="btn primary" type="submit">Add timestamped entry</button></form></div><h2>Local analyst ledger</h2>${c.entries.length?c.entries.slice().reverse().map(x=>`<article class="card spaced"><div class="row between"><span class="kicker">${esc(x.type)} · ${esc(x.at)}</span><button class="btn sm danger" data-act="delete-entry" data-id="${esc(x.id)}">Delete</button></div><p>${esc(x.text)}</p>${x.url?link(x.url,'Source / reference'):''}</article>`).join(''):'<div class="notice">No entries. The absence of a challenge log does not imply a robust plan.</div>'}<h2>Red-team scenarios</h2><div class="grid">${[['Non-acceptance','Either principal party refuses or disputes authority.'],['Implementation gap','Text agreed; monitor access, money or logistics withheld.'],['Asymmetric incentives','One party can defect while retaining the benefits.'],['Civilian externalities','A compromise risks coercion, displacement, exposure or denial of humanitarian rights.'],['Spoiler action','Actors outside the draft undermine compliance; do not assign intent without evidence.'],['Durability failure','Agreement survives an announcement but collapses under leadership, funding or battlefield changes.']].map(([h,t])=>`<div class="card"><h3>${h}</h3><p>${t}</p><button class="btn sm" data-act="log-risk" data-text="${esc(h+': '+t+' Mitigation and evidence pending.')}">Add to ledger</button></div>`).join('')}</div>`}
function evidence(){let all=[...SOURCES.map(x=>({...x,origin:'Curated baseline'})),...state.userSources.map(x=>({...x,origin:'User entry · unverified'}))];let q=ui.q.toLowerCase(),shown=all.filter(x=>!q||searchText(x).includes(q));return banner('Source register & provenance','Dated official texts, monitoring reports and attributed reporting. Source existence does not establish truth of every claim or permission to act. Manually review freshness before each external use.','STATIC SNAPSHOT: 16 OCT 2026')+`<div class="notice research"><b>Online/offline distinction:</b> this ledger is bundled with the application and available offline; it does not crawl, ingest, classify or verify live sources. The external links require connectivity and may change. Reporting after the research freeze is not automatically represented.</div><div class="card spaced"><h2>Record a public source</h2><form id="sourceForm"><div class="formgrid"><label class="field">Short title<input required name="name" maxlength="150" placeholder="Institution and publication title"></label><label class="field">Publication date<input name="date" required type="date" max="2100-01-01"></label><label class="field">Source type<select name="class">${selection('USER-REPORTED',[['OFFICIAL POSITION','Official position'],['INSTITUTIONAL RECORD','Institutional record'],['MONITORING REPORT','Monitoring report'],['NEWS REPORTING','News reporting'],['ACADEMIC ANALYSIS','Academic analysis'],['USER-REPORTED','Other / user claim']])}</select></label><label class="field">Public URL<input required name="url" type="url" maxlength="1500" placeholder="https://…"></label><label class="field wide">Precisely attributable claim<textarea name="claim" required maxlength="1800" placeholder="What does this source actually say? Distinguish reporting from verified fact."></textarea></label><label class="field wide">Limits, contradictions or next verification<textarea name="implication" maxlength="900" placeholder="What this record does not establish"></textarea></label></div><button class="btn primary">Add source to local register</button></form></div><h2>References (${shown.length})</h2><div class="grid">${shown.map(x=>`<article class="card"><div class="kicker">${esc(x.date)} · ${esc(x.class)}</div><h3>${esc(x.name)}</h3>${chip(x.origin,x.origin==='Curated baseline'?'':'warn')}<p>${esc(x.claim)}</p><p class="small muted"><b>Limitation / implication:</b> ${esc(x.implication||'Review before use.')}</p>${link(x.url,'Open source')}${x.origin!=='Curated baseline'?`<div class="actions"><button class="btn sm danger" data-act="remove-source" data-id="${esc(x.id)}">Remove local entry</button></div>`:''}</article>`).join('')||'<p>No matching source records.</p>'}</div><div class="card spaced"><h3>Research prompt chains (manual; external browsing)</h3><p>Use reproducible search terms to seek corroboration, explicit authorization and dissenting evidence. Opening search is voluntary and sends the query to the selected external search provider.</p><div class="actions">${[['Public bilateral positions','Russia Ukraine ceasefire October 2026 official statements terms'],['Security guarantees','Ukraine security guarantees 2026 treaty funding domestic ratification'],['Monitoring mandate','OSCE ceasefire monitoring mandate access lessons Ukraine'],['Humanitarian verification','ICRC Ukraine humanitarian safe passage agreement parties consent'],['Sanctions implementation','EU Ukraine Russia sanctions changes legal regulation October 2026']].map(([label,q])=>`<a class="btn sm" target="_blank" rel="noopener noreferrer" href="https://www.google.com/search?q=${encodeURIComponent(q)}">${esc(label)} ↗</a>`).join('')}</div></div>`}
function collaboration(){let p=ui.peer,c=current();return banner('Peer review room','Optional experimental peer-to-peer connection for non-sensitive, voluntary draft review. The default public room is unmoderated and cannot authenticate participants. No automatic upload, messaging or cross-device sync.','ONLINE ONLY · EXPRESS OPT-IN')+`<div class="notice critical"><b>Public room safety:</b> public relay infrastructure and connected peers may receive network metadata. Share only public or non-sensitive policy-draft summaries; never send names of protected people, negotiation contacts, frontline locations or confidential records. The default room is neither vetted nor moderated.</div><div class="card spaced"><div class="formgrid"><label class="field">Room code<input id="roomCode" maxlength="64" value="${esc(p.code)}" ${p.state==='connecting'||p.state==='connected'||p.state==='waiting'?'disabled':''}></label><label class="field">Signaling mechanism<select id="strategy" ${p.state==='connecting'||p.state==='connected'||p.state==='waiting'?'disabled':''}><option value="nostr" ${p.strategy==='nostr'?'selected':''}>Nostr via Trystero</option><option value="mqtt" ${p.strategy==='mqtt'?'selected':''}>MQTT via Trystero</option></select></label></div><p><b>Connection state:</b> ${esc(p.state)} · <b>Confirmed peers:</b> ${p.peers.size}</p>${p.error?`<p class="notice critical">${esc(p.error)}</p>`:''}<div class="actions"><button class="btn primary" data-act="join-room" ${['connecting','waiting','connected'].includes(p.state)?'disabled':''}>Join (explicit consent)</button><button class="btn" data-act="leave-room" ${!['connecting','waiting','connected'].includes(p.state)?'disabled':''}>Disconnect</button><button class="btn" data-act="private-room" ${['connecting','waiting','connected'].includes(p.state)?'disabled':''}>New private code</button><button class="btn" data-act="public-room" ${['connecting','waiting','connected'].includes(p.state)?'disabled':''}>Public default</button><button class="btn" data-act="copy-invite">Copy invitation</button></div><p class="small muted">Network transport is imported only after Join, using public external services. HTTPS/localhost required. No TURN is configured here, so corporate networks and certain NATs may prevent connections. Connected peers are not identity-verified.</p></div><div class="two"><div class="card"><h2>Outgoing review</h2>${c?`<p>Selected local draft: <b>${esc(c.title)}</b>. Only a shortened title, issue family and summary are sent, never your gates, evidence URLs or local risk ledger.</p><label class="field"><input type="checkbox" id="shareConsent" style="width:auto;min-height:0"> I reviewed the content and accept public peer exposure.</label><div class="actions"><button class="btn primary" data-act="share-case" ${p.peers.size===0?'disabled':''}>Send limited draft to peers</button></div>`:'<p>Create or select a draft in the workbench before sharing.</p>'}</div><div class="card"><h2>Incoming, quarantined drafts (${p.incoming.length})</h2>${p.incoming.length?p.incoming.map((x,i)=>`<div class="decision"><span class="kicker">Unverified peer: ${esc(x.peer.slice(0,12))}</span><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><div class="actions"><button class="btn sm" data-act="accept-draft" data-index="${i}">Import as unverified case</button><button class="btn sm danger" data-act="discard-draft" data-index="${i}">Discard</button></div></div>`).join(''):'<p>No messages received. An empty inbox does not imply a global room has no participants.</p>'}</div></div>`}
function settings(){return banner('Workspace & portable data','All authored cases, sources and decision entries are local until you explicitly export, import or send a short peer-review draft. No tracking, hidden synchronization or cloud account.','PRIVACY · BACKUPS · MAINTENANCE')+`<div class="grid"><div class="card"><h2>Local data</h2><p>Storage: <b>${esc(store)}</b></p><p>${state.cases.length} cases and ${state.userSources.length} authored sources saved in this workspace.</p><div class="actions"><button class="btn primary" data-act="export-backup">Export validated JSON backup</button><button class="btn" data-act="export-catalog">Export research catalog</button></div><label class="field">Import workspace backup (.json, including original v1.1 workspace exports)<input id="backupFile" type="file" accept="application/json,.json"></label><p class="small muted">Legacy XP/completion is not migrated; legacy saved proposals can become unverified research cases.</p><button class="btn danger" data-act="reset">Erase local workspace</button></div><div class="card"><h2>Accessibility & operation</h2><label class="field">Appearance<select id="themeSelect">${selection(state.prefs.theme,[['light','Light'],['dark','Dark']])}</select></label><h3>Offline readiness</h3><p id="swInfo">${location.protocol==='file:'?'File mode: core catalog works without service worker; browser storage may vary.':'Hosted mode: checking active cache…'}</p><p>Hosted HTTPS/localhost installs a small versioned offline shell after a successful visit. External source websites and real-time peer transport do not work offline.</p><button class="btn" data-act="check-sw">Check offline cache status</button></div></div><h2>Data stewardship</h2><div class="notice warning">Back up before import or reset. Imported entries are untrusted user statements and are escaped when displayed. Never add protected-person data or sensitive operational details. An evidence URL can document what a source says, not independently prove a party's consent.</div>`}
function download(obj,name,type='application/json'){let txt=typeof obj==='string'?obj:JSON.stringify(obj,null,2);let a=document.createElement('a'),url=URL.createObjectURL(new Blob([txt],{type:type+';charset=utf-8'}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function memo(c){const a=assessment(c),s=issueBy[c.issueId]||ISSUES[0];const line=s=>String(s??'').replace(/\r/g,'').replace(/[\x00-\x08]/g,'');let lines=['# '+line(c.title),'','**Classification:** INDEPENDENT RESEARCH DRAFT — NOT AUTHORIZED OR AGREED','**Exported:** '+stamp(),'**Issue family:** '+groupFor(s.category),'**Documented status:** '+a.status,'','## Scope',line(c.description),'',line(c.scope),'','## Proposed institutional owner',line(c.owner||'NOT ESTABLISHED'),'## Proposed venue',line(c.forum||'NOT ESTABLISHED'),'','## Proposed stakeholders',...c.actors.map(x=>'- '+line(actorBy[x.id]?.name||x.id)+' — '+line(x.role)+' (engagement not verified)'),'','## Gate register'];for(let g of reqGates(c)){let x=c.gates[g.id]||{};lines.push('### '+g.name,'Status: '+(x.state||'unknown'),'Basis: '+line(x.note||'NOT ESTABLISHED'),'Reference: '+line(x.url||'none'),'')};lines.push('## Monitoring and implementation',...Object.entries(c.protocol||{}).map(([k,v])=>'### '+k+'\n'+line(v||'NOT SPECIFIED')),'','## Bargaining incentive hypotheses (not accepted by parties)',...['ukraine','russia','implementer'].flatMap(k=>['### '+k,...Object.entries(c.incentives?.[k]||{}).map(([field,value])=>field+': '+line(value))]),'','## Analyst ledger',...c.entries.map(x=>'- ['+x.at+'] '+x.type+': '+line(x.text)+(x.url?' ('+x.url+')':'')),'','## Next legitimate step',line(c.next),'','## Source discipline','References are user-entered unless curated in the source register. No independently verified authority, acceptance, implementation or diplomatic efficacy is implied.','');return lines.join('\n')}
function normalize(w){if(!w||w.schema!==2||!Array.isArray(w.cases)||!Array.isArray(w.userSources)||w.cases.length>500||w.userSources.length>1500)throw Error('Unsupported or oversized workspace');let out=fresh();out.cases=w.cases.filter(c=>c&&typeof c==='object'&&issueBy[c.issueId]).slice(0,500).map(c=>({id:trim(c.id,100)||id('import'),title:trim(c.title,170)||'Imported research case',issueId:c.issueId,category:issueBy[c.issueId].category,description:trim(c.description,3000),owner:trim(c.owner,170),forum:trim(c.forum,170),scope:trim(c.scope,3000),next:trim(c.next,3000),actors:Array.isArray(c.actors)?c.actors.filter(x=>x&&actorBy[x.id]).slice(0,30).map(x=>({id:x.id,role:trim(x.role,140),status:'proposed'})):[],gates:Object.fromEntries(Object.entries(c.gates||{}).filter(([k])=>GATES.some(g=>g.id===k)).map(([k,x])=>[k,{state:['unknown','blocked','documented'].includes(x?.state)?x.state:'unknown',url:trim(x?.url,1500),note:trim(x?.note,800)}])),protocol:Object.fromEntries(Object.keys(DEFAULT_PROTOCOL).map(k=>[k,trim(c.protocol?.[k],2200)])),incentives:normalizeIncentives(c.incentives),entries:Array.isArray(c.entries)?c.entries.slice(0,800).map(x=>({id:trim(x.id,100)||id('entry'),type:trim(x.type,35),text:trim(x.text,2400),url:trim(x.url,1500),at:trim(x.at,40)})):[],created:trim(c.created,40),updated:stamp(),status:'EXPLORATORY / UNAUTHORIZED'}));out.userSources=w.userSources.filter(x=>x&&allowedUrl(x.url)&&trim(x.name,150)).slice(0,1500).map(x=>({id:trim(x.id,100)||id('source'),name:trim(x.name,150),date:trim(x.date,12),class:trim(x.class,60),claim:trim(x.claim,1800),url:trim(x.url,1500),implication:trim(x.implication,900)}));out.prefs.theme=w.prefs?.theme==='dark'?'dark':'light';return out}
function importLegacy(w){if(w.schema!==1||!w.workspace||!Array.isArray(w.workspace.plans))throw Error('Invalid legacy backup');let out=fresh();out.cases=w.workspace.plans.filter(x=>x&&issueBy[x.solutionId]).slice(0,500).map(x=>{let c=caseFactory(x.solutionId);c.title=trim(x.title,170)||c.title;c.description=trim(x.summary,3000);c.scope='Imported v1.1 hypothetical proposal. Previously assigned seats and scores are not validated as institutional commitments.';c.actors=(x.seats||[]).filter(y=>actorBy[y.entity]).slice(0,30).map(y=>({id:y.entity,role:trim(y.seat,140),status:'proposed'}));return c});return out}
async function importFile(file){if(!file)return;if(file.size>6*1024*1024){showToast('File too large (>6 MB).');return}try{let raw=JSON.parse(await file.text()),w=raw.schema===1?importLegacy(raw):normalize(raw);if(!confirm('Replace the current local workspace with this imported file? Export your existing data first.'))return;state=w;ui.caseId=state.cases[0]?.id||null;save();render();showToast('Imported as unverified local research drafts.')}catch(e){showToast('Import rejected: '+e.message)}}
function addCase(issueId){let c=caseFactory(issueId);state.cases.unshift(c);ui.caseId=c.id;ui.issue=c.issueId;save();location.hash='#/workbench';render();showToast('Created unverified research draft. No institutional authorization assumed.')}
async function connectPeer(){let p=ui.peer,el=$('roomCode'),code=trim(el?.value,64);if(!/^[A-Za-z0-9_-]{8,64}$/.test(code))return showToast('Use 8–64 characters (letters, numbers, - or _).');if(location.protocol==='file:'||!navigator.onLine)return showToast('Network + HTTPS/localhost are needed; local tools still work.');p.code=code;p.strategy=$('strategy')?.value==='mqtt'?'mqtt':'nostr';p.state='connecting';p.error='';render();try{let module=await import(p.strategy==='mqtt'?'https://esm.run/@trystero-p2p/mqtt@0.26.0':'https://esm.run/trystero@0.26.0');let room=module.joinRoom({appId:'org.planetary-restoration-archive.peace-pathways-os.v3'},code,{onJoinError:({error})=>{p.error=String(error?.message||error);p.state='error';render()}});p.room=room;let a=room.makeAction('review-memo');p.action=a;a.onMessage=(obj,peer)=>{if(!obj||obj.type!=='memo'||typeof obj.title!=='string'||obj.title.length>170||typeof obj.summary!=='string'||obj.summary.length>900||!issueBy[obj.issueId])return;p.incoming.push({title:obj.title,summary:obj.summary,issueId:obj.issueId,peer:typeof peer==='string'?peer:peer?.peerId||'unknown'});p.incoming=p.incoming.slice(-25);if(ui.route==='collaboration')render()};room.onPeerJoin=peer=>{p.peers.add(peer);p.state='connected';if(ui.route==='collaboration')render()};room.onPeerLeave=peer=>{p.peers.delete(peer);p.state=p.peers.size?'connected':'waiting';if(ui.route==='collaboration')render()};p.state='waiting';render();showToast('Room joined; only confirmed peers are counted.')}catch(e){p.state='error';p.error=String(e.message||e);render();showToast('Peer transport failed; local work unaffected.')}}
async function disconnect(){try{await ui.peer.room?.leave()}catch{}ui.peer.room=null;ui.peer.action=null;ui.peer.peers.clear();ui.peer.state='disconnected';ui.peer.error='';render()}
function invite(){let u;if(location.protocol==='file:')u=ui.peer.code;else{u=new URL(location.href);u.searchParams.set('room',ui.peer.code);u.searchParams.set('strategy',ui.peer.strategy);u.hash='#/collaboration';u=u.toString()}if(navigator.clipboard?.writeText)navigator.clipboard.writeText(String(u)).then(()=>showToast('Invite copied.')).catch(()=>showToast('Clipboard blocked; copy room code manually.'));else showToast('Clipboard unavailable: '+String(u))}
async function cacheStatus(){let t=$('swInfo');if(!t)return;if(location.protocol==='file:'){t.textContent='File mode supports local static use. Service workers require HTTPS or localhost.';return}try{let reg=await navigator.serviceWorker?.getRegistration();t.textContent=reg?.active?'Active offline shell cache is registered; external URLs and peers still require internet.':'Service worker not yet active; HTTPS/localhost and successful first online visit required.'}catch{t.textContent='Cannot verify offline cache installation.'}}
function updateGate(el){let c=current(),k=el.dataset.gate,part=el.dataset.part;if(!c||!GATES.some(x=>x.id===k)||!['state','url','note'].includes(part))return;let v=trim(el.value,part==='note'?800:1500);if(part==='state'&&!['unknown','blocked','documented'].includes(v))return;c.gates[k]??={state:'unknown',url:'',note:''};c.gates[k][part]=v;c.updated=stamp();save()}

/* Multi-track institutional matrix: source-linked options, never a diplomacy simulator. */
GATES.push(
 {id:'scope-sovereignty',name:'Sovereignty and constitutional compatibility',details:'No illegal annexation, displacement-driven consultation or unilateral interim administration. A cooling period alone confers no authority.',for:s=>s.trackId==='t2'},
 {id:'human-safeguard',name:'Human-supervised clearance certification',details:'All releases must be done by accredited mine-action authorities and independently quality assured; an AI output is not proof of safety.',for:s=>s.id==='ai-assisted-mine-action'},
 {id:'nuclear-mandate',name:'Nuclear monitor acceptance and power/safety continuity',details:'IAEA assessment is not enforcement. Specify protective commitment and safe access of appropriate professionals.',for:s=>s.id==='nuclear-safety-zone'},
 {id:'frozen-yields',name:'Sovereign-asset proceeds and applicable legal authority',details:'Distinguish extraordinary returns from principal; authorize each custody and transfer mechanism under applicable law.',for:s=>s.id==='russian-asset-yield-fund'},
 {id:'maritime-risk',name:'Civilian vessel protection and AIS publication safety',details:'No live route publication; maritime safety requires consent, insurance, shipping/regulatory oversight and independent review.',for:s=>s.id==='maritime-civilian-corridor'},
 {id:'sensor-protection',name:'Telemetry data minimization and anti-targeting assurance',details:'No publishable raw drone feeds or tactical positions; evaluate chain-of-custody and false alarms.',for:s=>s.id==='sensor-verification'},
 {id:'grid-operators',name:'Existing interconnection and grid safety review',details:'ENTSO-E synchronization has existed since 2022; secure operator-reviewed resilience projects.',for:s=>s.id==='entsoe-restoration'}
);
function normalizeIncentives(value){let out={};for(let who of ['ukraine','russia','implementer']){out[who]={};for(let key of ['outside','minimum','exchange','credibility','blocker','source'])out[who][key]=trim(value?.[who]?.[key],1200)}return out}
function matrix(){let visible=PATHWAYS.filter(p=>(ui.matrixTrack==='all'||p.trackId===ui.matrixTrack)&&(!ui.q||searchText(p).includes(ui.q))),cur=visible.find(p=>p.id===ui.matrixPath)||visible[0],sol=issueBy[cur?.solutionIds?.[0]];
const count=(t,p)=>PATHWAYS.filter(x=>x.trackId===t&&x.phaseId===p).length;
return banner('Multi-track diplomacy matrix','Compare conditional policy instruments against actual decision rights, applicable law, monitoring competence, veto points, incentive compatibility and independently auditable civilian outcomes. Nothing is an agreed plan.','THREE TRACKS · PHASED OPTIONS · HUMAN AUTHORIZATION')+
`<div class="notice critical"><b>Law and operational limits:</b> This is a policy-level analysis tool. Thirty kilometres is a hypothesis, not an agreed artillery arrangement. A five-year cooling period does not legalize a territorial referendum. IAEA safety monitoring is not coercive enforcement; AIS observations do not ensure safe passage. No live telemetry, military locations or identifiable protected-person data.</div>
<div class="card spaced"><h2>Track × phase coverage</h2><div class="tablewrap"><table><thead><tr><th>Track / phase</th>${PHASES.map(p=>`<th>${esc(p.title)}</th>`).join('')}</tr></thead><tbody>${TRACKS.map(t=>`<tr><th>${esc(t.title)}</th>${PHASES.map(p=>`<td>${count(t.id,p.id)?chip(count(t.id,p.id)+' proposed mechanisms','warn'):'No modeled mechanism'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">Matrix cells describe the catalog, not implementation progress. Phases are conceptual and can overlap or be abandoned.</p></div>
<div class="grid">${PHASES.map(ph=>`<section class="card"><h3>${esc(ph.title)}</h3><p>${esc(ph.objective)}</p><details><summary>Entry and exit conditions</summary><b>Entry:</b><ul>${ph.entryConditions.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><b>Evidence needed for exit:</b><ul>${ph.exitCriteria.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p><b>Fallback:</b> ${esc(ph.fallback)}</p></details></section>`).join('')}</div>
<div class="card spaced"><label class="field" style="max-width:480px">Filter by diplomatic track<select id="matrixTrack">${selection(ui.matrixTrack,[['all','All tracks'],...TRACKS.map(t=>[t.id,t.title])])}</select></label></div>
<div class="catalog-layout"><div class="card"><h2>Candidate mechanisms (${visible.length})</h2><div class="catalog-scroll" tabindex="0">${visible.map(p=>`<button class="clickrow" data-act="select-path" data-id="${esc(p.id)}" aria-pressed="${p.id===cur?.id}"><strong>${esc(p.title)}</strong><small>${esc(p.trackId.toUpperCase())} · ${esc(p.phaseId.toUpperCase())} · Not authorized</small></button>`).join('')||'<p>No proposals match. Clear your search or change the track filter.</p>'}</div></div>
${!cur?'<article class="card">No pathway selected.</article>':`<article class="card profile-scroll" tabindex="0" aria-label="Scrollable mechanism evidence dossier"><span class="kicker">${esc(cur.trackId.toUpperCase())} / ${esc(cur.phaseId.toUpperCase())} · CONDITIONAL DRAFT</span><h2>${esc(cur.title)}</h2><p>${esc(cur.hypothesis)}</p><h3>Legitimacy and consent prerequisites</h3><ul>${cur.preconditions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>High-level mechanism</h3><ol>${cur.mechanisms.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>Strategic incentive and veto tests</h3>${cur.incentiveTests.map(x=>`<div class="decision"><b>${esc(x.actor)}</b><p>${esc(x.question)}</p></div>`).join('')}<details><summary>Explicit failure/veto register</summary><ul>${cur.vetoPoints.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><h3>Risk mitigations and stop triggers</h3>${cur.riskMitigations.map(x=>`<p><b>${esc(x.risk)}:</b> ${esc(x.mitigation)}<br><span class="small muted">Stop/review: ${esc(x.stopOrReviewTrigger)}</span></p>`).join('')}<h3>Quantitative measurements (targets proposed, baselines unverified)</h3>${(sol?.metrics||[]).map(m=>`<div class="decision"><b>${esc(m.label)}</b> ${chip(m.unit)}<p>${esc(m.definition)}</p><p><b>Proposed target:</b> ${esc(m.proposalTarget)}<br><b>Actual baseline:</b> ${esc(m.baseline)}<br><b>Validation:</b> ${esc(m.validation)}</p></div>`).join('')}<h3>Attributable sources</h3><ul>${cur.sourceIds.map(x=>{let src=SOURCES.find(e=>e.id===x);return `<li>${src?link(src.url,src.name):esc('Unresolved source: '+x)}</li>`}).join('')}</ul><h3>If the mechanism fails</h3><p>${esc(cur.fallback)}</p><div class="actions"><button class="btn primary" data-act="example" data-issue="${esc(cur.solutionIds[0])}">Open as research case</button><button class="btn" data-act="export-pathway" data-id="${esc(cur.id)}">Export complete pathway memo</button><a href="#/bargaining" class="btn">Test bargaining assumptions</a></div></article>`}</div>`}
function bargaining(){let c=current();if(!c)return banner('Incentives, veto points and credible commitments','Create a policy case first to document the bilateral or multilateral bargaining hypothesis.')+'<a class="btn primary" href="#/matrix">Choose a pathway</a>';
let v=normalizeIncentives(c.incentives),title={ukraine:'Ukrainian authorized decision owner',russia:'Russian authorized decision owner',implementer:'Third-party monitor / funder / guarantor (if separately accepting)'};
let fields=[['outside','Outside option (BATNA); public evidence vs inference','What happens if no arrangement is accepted? Avoid invented military forecasts.'],['minimum','Minimum lawful acceptance condition','What is the non-negotiable constraint? Who is authorized to decide?'],['exchange','Contingent reciprocal change / enforceability','What concrete concession or restraint is testable, and who can commit?'],['credibility','Commitment credibility and domestic ratification','What mandate, funding, verification and response to breach would make it believable?'],['blocker','Spoiler, veto or failure of incentive alignment','How could parties rationally reject this arrangement?'],['source','Public source / evidence state','Public URL or explicit UNSOURCED INFERENCE; documentation is not consent']];
return banner('Incentives and credible commitments','Record actor-specific outside options and conditional offers without assigning invented utilities or probabilities. An analyst cannot decide whether a real actor prefers a proposal.','QUALITATIVE BARGAINING MATRIX · NO SIMULATED AGREEMENT')+`<div class="notice warning"><b>Feasibility invariant:</b> Without compatible authoritative commitments, there is no demonstrated bargain. This section saves analyst hypotheses only. It does not send diplomatic communication or model battlefield positions.</div><div class="card spaced"><h2>${esc(c.title)}</h2><form id="bargainingForm">${['ukraine','russia','implementer'].map(who=>`<fieldset><legend>${esc(title[who])}</legend><div class="formgrid">${fields.map(([key,label,hint])=>`<label class="field">${esc(label)}<textarea name="${who}_${key}" maxlength="1200" placeholder="${esc(hint)}">${esc(v[who][key])}</textarea></label>`).join('')}</div></fieldset>`).join('')}<div class="actions"><button class="btn primary" type="submit">Save incentive matrix</button><button type="button" class="btn" data-act="export-memo">Export with case memorandum</button></div></form></div><div class="two"><div class="card"><h3>Two-sided feasibility test</h3><p><b>Individual rationality:</b> Each decision owner must judge the option preferable to its own alternative, but no analyst may assert this without evidence.</p><p><b>Incentive compatibility:</b> The arrangement must remain feasible when credible disagreement, verification evasion and domestic ratification risks are included.</p><p><b>Credible commitment:</b> Mandate, third-party acceptance, auditable restraints and a proportionate non-compliance process.</p></div><div class="card warn"><h3>Do not turn hypotheses into facts</h3><p>Publicly stated preferences can differ from negotiable positions. Unknown is a legitimate outcome. Keep consent, lawful sovereignty, humanitarian obligations and safety gates separate from bargaining leverage.</p><a href="#/workbench" class="btn">Review hard authorization gates</a></div></div>`}

function handlers(){document.addEventListener('click',async e=>{let b=e.target.closest('[data-act]');if(!b)return;const act=b.dataset.act,c=current();switch(act){case 'select-actor':ui.actor=b.dataset.id;render();break;case 'select-issue':ui.issue=b.dataset.id;render();break;case 'select-path':ui.matrixPath=b.dataset.id;render();break;case 'export-pathway':{let pt=PATHWAYS.find(x=>x.id===b.dataset.id);if(pt){let sol=issueBy[pt.solutionIds[0]];download(['# '+pt.title,'','**Classification:** UNVERIFIED ANALYTICAL OPTION — NO MANDATE','**Snapshot:** '+DATA.asOf,'','## Hypothesis',pt.hypothesis,'','## Preconditions',...pt.preconditions.map(x=>'- '+x),'','## Mechanisms',...pt.mechanisms.map(x=>'- '+x),'','## Veto / refusal points',...pt.vetoPoints.map(x=>'- '+x),'','## Incentive tests',...pt.incentiveTests.map(x=>'- '+x.actor+': '+x.question),'','## Risks',...pt.riskMitigations.map(x=>'- '+x.risk+' → '+x.mitigation),'','## Proposed metrics',...(sol?.metrics||[]).map(x=>'- '+x.label+' ('+x.unit+') — '+x.definition+'; baseline: '+x.baseline+'; target: '+x.proposalTarget),'','## Source IDs',...pt.sourceIds.map(x=>'- '+x+' — '+(SOURCES.find(e=>e.id===x)?.url||'source not found')),'','## Fallback',pt.fallback].join('\n'),'pathway_'+pt.id+'.md','text/markdown')}break;}case 'example':addCase(b.dataset.issue);break;case 'new-case':addCase(ui.issue);break;case 'delete-case':if(c&&confirm('Delete this research case and all its local entries?')){state.cases=state.cases.filter(x=>x.id!==c.id);ui.caseId=state.cases[0]?.id||null;save();render()}break;case 'case-actor':if(!c)return showToast('Create a case first.');if(!c.actors.some(x=>x.id===b.dataset.id)){c.actors.push({id:b.dataset.id,role:'Proposed — role to validate',status:'unverified'});save();showToast('Proposed participant added; acceptance unverified.')}location.hash='#/workbench';render();break;case 'add-actor':if(!c)return;let aid=$('actorAdder')?.value,role=trim($('roleAdder')?.value,140)||'Role not yet established';if(actorBy[aid]&&!c.actors.some(x=>x.id===aid)){c.actors.push({id:aid,role,status:'unverified'});save();render()}else showToast('Already included or invalid actor.');break;case 'remove-actor':if(c){c.actors.splice(Number(b.dataset.index),1);save();render()}break;case 'review':save();render();showToast('Prerequisites reassessed as user documentation, not external authorization.');break;case 'export-memo':if(c)download(memo(c),'peace_case_'+c.id+'.md','text/markdown');break;case 'export-case':if(c)download({schema:2,case:c,classification:'UNVERIFIED INDEPENDENT DRAFT'},'peace_case_'+c.id+'.json');break;case 'delete-entry':if(c&&confirm('Remove this local ledger entry?')){c.entries=c.entries.filter(x=>x.id!==b.dataset.id);save();render()}break;case 'log-risk':if(c){c.entries.push({id:id('entry'),at:stamp(),type:'risk',url:'',text:trim(b.dataset.text,2400)});save();render()}break;case 'remove-source':if(confirm('Remove this locally authored source?')){state.userSources=state.userSources.filter(x=>x.id!==b.dataset.id);save();render()}break;case 'export-backup':download(state,'peace_accord_workbench_backup.json');break;case 'export-catalog':download(DATA,'peace_accord_reference_catalog.json');break;case 'reset':if(confirm('Permanently erase ALL local cases, sources and decisions on this device?')&&confirm('Final confirmation: have you exported a backup?')){state=fresh();save();render()}break;case 'join-room':void connectPeer();break;case 'leave-room':void disconnect();break;case 'private-room':ui.peer.code='peace-'+Array.from(crypto.getRandomValues(new Uint8Array(12))).map(x=>x.toString(16).padStart(2,'0')).join('');render();break;case 'public-room':ui.peer.code='peace-pathways-community-v1';render();break;case 'copy-invite':invite();break;case 'share-case':if(!c||!ui.peer.peers.size||!$('shareConsent')?.checked)return showToast('Peer connection and explicit review consent are both required.');try{await ui.peer.action.send({type:'memo',title:trim(c.title,170),summary:trim(c.description,900),issueId:c.issueId});showToast('Limited draft sent to connected peers.')}catch{showToast('Sharing failed.')}break;case 'accept-draft':{let m=ui.peer.incoming.splice(Number(b.dataset.index),1)[0];if(m&&issueBy[m.issueId]){let draft=caseFactory(m.issueId);draft.title=m.title;draft.description=m.summary;draft.scope='Imported from an unverified public peer. Validate independently.';state.cases.unshift(draft);ui.caseId=draft.id;save();location.hash='#/workbench';render()}break}case 'discard-draft':ui.peer.incoming.splice(Number(b.dataset.index),1);render();break;case 'check-sw':void cacheStatus();break;}});
 document.addEventListener('submit',e=>{if(!['caseForm','protocolForm','entryForm','sourceForm','bargainingForm'].includes(e.target.id))return;e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f).entries()),c=current();if(f.id==='caseForm'&&c){if(!trim(d.title))return showToast('Case title is required.');let previous=c.issueId;c.title=trim(d.title,170);c.issueId=issueBy[d.issueId]?d.issueId:previous;c.category=issueBy[c.issueId].category;c.owner=trim(d.owner,170);c.forum=trim(d.forum,170);c.description=trim(d.description,3000);c.scope=trim(d.scope,3000);c.next=trim(d.next,3000);ui.issue=c.issueId;c.updated=stamp();save();render();showToast('Case definition saved. Changes in issue family may change required gates.')}else if(f.id==='protocolForm'&&c){for(const k of Object.keys(DEFAULT_PROTOCOL))c.protocol[k]=trim(d[k],2200);c.updated=stamp();save();showToast('Draft verification protocol saved locally.')}else if(f.id==='bargainingForm'&&c){c.incentives={};for(const who of ['ukraine','russia','implementer']){c.incentives[who]={};for(const key of ['outside','minimum','exchange','credibility','blocker','source'])c.incentives[who][key]=trim(d[who+'_'+key],1200)}c.updated=stamp();save();render();showToast('Incentive hypotheses saved; no party acceptance established.')}else if(f.id==='entryForm'&&c){if(!trim(d.text))return;if(d.url&&!allowedUrl(d.url))return showToast('Use a valid public HTTP(S) URL.');c.entries.push({id:id('entry'),at:stamp(),type:trim(d.type,35),text:trim(d.text,2400),url:trim(d.url,1500)});save();render();showToast('Local analyst entry recorded.')}else if(f.id==='sourceForm'){if(!allowedUrl(d.url))return showToast('Use a valid HTTP(S) source URL.');if(!trim(d.name)||!trim(d.claim))return showToast('Name and claim are required.');state.userSources.push({id:id('source'),name:trim(d.name,150),date:trim(d.date,12),class:trim(d.class,60),url:trim(d.url,1500),claim:trim(d.claim,1800),implication:trim(d.implication,900)});save();render();showToast('User-provided source saved; content not externally verified.')}});
 document.addEventListener('change',e=>{let t=e.target;if(t.dataset.gate)return updateGate(t);if(t.id==='caseSelect'){ui.caseId=t.value;render()}if(t.id==='backupFile')void importFile(t.files?.[0]);if(t.id==='matrixTrack'){ui.matrixTrack=t.value;ui.matrixPath=PATHWAYS.find(p=>t.value==='all'||p.trackId===t.value)?.id||'';render()}if(t.id==='themeSelect'){state.prefs.theme=t.value==='dark'?'dark':'light';save();render()}});
 $('globalSearch').addEventListener('input',e=>{ui.q=e.target.value.toLowerCase().trim().slice(0,200);if(!['stakeholders','issues','evidence','matrix'].includes(ui.route)){location.hash='#/stakeholders'}else render()});$('themeToggle').addEventListener('click',()=>{state.prefs.theme=state.prefs.theme==='dark'?'light':'dark';save();render()});$('menuToggle').addEventListener('click',()=>{let nav=$('nav'),open=!nav.classList.contains('open');nav.classList.toggle('open',open);$('menuToggle').setAttribute('aria-expanded',String(open));if(open)nav.querySelector('a')?.focus()});document.addEventListener('keydown',e=>{if(!$('nav').classList.contains('open'))return;if(e.key==='Escape'){$('nav').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');$('menuToggle').focus()}else if(e.key==='Tab'){const els=Array.from($('nav').querySelectorAll('a,button')).filter(x=>!x.disabled);const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});window.addEventListener('hashchange',()=>{route();$('main').focus({preventScroll:true})});window.addEventListener('online',()=>{if(ui.route==='collaboration')render();else $('netStatus').textContent='Online · local data'});window.addEventListener('offline',()=>{$('netStatus').textContent='Offline · local data'});window.addEventListener('beforeunload',()=>{if(ui.peer.room)void ui.peer.room.leave()});}
async function boot(){let loaded=await load();if(loaded){try{state=normalize(loaded)}catch{showToast('Stored data unreadable; new session. Export earlier backups if available.')}}ui.caseId=state.cases[0]?.id||null;let params=new URLSearchParams(location.search),room=trim(params.get('room'),64);if(/^[A-Za-z0-9_-]{8,64}$/.test(room))ui.peer.code=room;ui.peer.strategy=params.get('strategy')==='mqtt'?'mqtt':'nostr';handlers();route();if('serviceWorker'in navigator&&location.protocol!=='file:'&&['https:','http:'].includes(location.protocol)){navigator.serviceWorker.register('./sw.js').catch(()=>{});} }
void boot();
})();
